import sys
import logging
from .testline import Testline


class HranConfig(Testline):

    def __init__(self, location, testline, env_config_id, provider=None):
        super(HranConfig, self).__init__(location, testline, env_config_id, provider)
        self.fsm_rel = []
        self._modules = None
        self.testline = testline
        self.pdu_general_info = []

    @property
    def hosts(self):
        msm_ip = self.msm_host_addr()
        esm_ip = self.esm_host_addr()
        return [self.host(addr) for addr in (msm_ip, esm_ip) if addr]

    @property
    def mplane_ip(self):
        return self._get_mplane_ip()

    @property
    def hw_type(self):
        return self._get_common_data('SMOD', 'HW_TYPE')

    @property
    def system_modules(self):
        return self.modules['fsm']

    @property
    def radio_modules(self):
        return self.modules['rf']

    @property
    def master_data(self):
        return self._get_common_data_component('MASTER')

    @property
    def slave_data(self):
        return self._get_common_data_component('SLAVE')

    @property
    def modules(self):
        if not self._modules:
            self._modules = {'rf': [], 'fsm': []}
            smod_hw_type = iter(self.hw_type)
            for interface, config in self.testline_parameters.TESTLINE_CONFIG_VARIABLES['INTERFACES'].items():
                if 'SMOD' in interface:
                    fsm = self._get_sm_list(config, next(smod_hw_type))
                    fsm.serial_num = interface.split('_')[-1]
                    self.pdu_general_info.append(fsm['pdu'])
                    self._modules['fsm'].append(fsm)
                elif 'RMOD' in interface:
                    rfmod = self.rf(config)
                    rfmod.serial_num = interface.split('_')[-1]
                    self.pdu_general_info.append(rfmod['pdu'])
                    self._modules['rf'].append(rfmod)
        return self._modules

    @property
    def rfs_modules(self):
        if not self._modules:
            self._modules = {'rf': [], 'fsm': []}
            smod_hw_type = iter(self._get_common_data(
                'MASTER', 'MASTER_MODULE_TYPE') + self._get_common_data('SLAVE', 'SLAVE_MODULE_TYPE'))
            self.get_rfs_hw(smod_hw_type)
        return self._modules

    def get_rfs_hw(self, smod_hw_type):
        for interface, config in self.testline_parameters.TESTLINE_CONFIG_VARIABLES['INTERFACES'].items():
            if 'SMOD' in interface:
                self.process_smod(config, smod_hw_type, interface)
            elif 'RMOD' in interface:
                self.process_rmod(config, interface)

    def process_smod(self, config, smod_hw_type, interface):
        fsm = self._get_sm_list(config, next(smod_hw_type))
        try:
            fsm.serial_num = interface.split('_')[-1]
            logging.info(interface)
        except AttributeError:
            logging.exception("An error has occured because active configuration is different than "
                              "interfaces.yaml file. Please update and check that interfaces.yaml is up to"
                              "date and is based on the configuration template and try again")
            sys.exit()
        fsm.contactor = config['CONTACTOR']
        self.pdu_general_info.append(fsm['pdu'])
        self._modules['fsm'].append(fsm)

    def process_rmod(self, config, interface):
        rfmod = self.rf(config)
        try:
            rfmod.serial_num = interface.split('_')[-1]
            logging.info(interface)
        except AttributeError:
            logging.exception("An error has occured because active configuration is different than "
                              "interfaces.yaml file. Please update and check that interfaces.yaml is up to"
                              "date and is based on the configuration template and try again")
            sys.exit()
        rfmod.contactor = config['CONTACTOR']
        self.pdu_general_info.append(rfmod['pdu'])
        self._modules['rf'].append(rfmod)

    @property
    def rnc(self):
        return self._get_rnc_data_dict()

    def _get_rnc_data_dict(self):
        try:
            rnc_dict = {
                'id': self._get_common_data('RNC', 'ID')[0],
                'rnc_ip': self._get_common_data('RNC', 'RNC_IP')[0],
                'oms_ip': self._get_common_data('RNC', 'OMS_IP')[0]
            }
            return self._add_rnc_login_and_password(rnc_dict)
        except (KeyError, IndexError):
            return {}

    @staticmethod
    def _add_rnc_login_and_password(rnc_dict):
        rnc_id = rnc_dict['id']
        if rnc_id == 31 or rnc_id == 34:
            rnc_dict['login'] = 'SYSTEM'
            rnc_dict['password'] = 'SYSTEM'
        elif rnc_id == 36 or rnc_id == 38:
            rnc_dict['login'] = 'nokiadmin'
            rnc_dict['password'] = 'system'
        else:
            rnc_dict['login'] = ''
            rnc_dict['password'] = ''
        return rnc_dict

    @property
    def bsc(self):
        try:
            name = self.env_config_testline_variables()['BSC']
            ip = self._get_common_data('BSC', 'ip')
            return name, ip
        except KeyError:
            return ()

    @property
    def ftp(self):
        ftp_server_name = self._get_ftp_server_name()
        return self._get_ftp_data(ftp_server_name) if ftp_server_name else None

    def _get_ftp_data(self, server_name):
        ftp_params = ['ip', 'port', 'user', 'password', 'download_path', 'upload_path']
        ftp_data_dict = {}
        for param in ftp_params:
            self._fill_ftp_dict(ftp_data_dict, server_name, param)
        return ftp_data_dict

    def _fill_ftp_dict(self, ftp_dict, server_name, param):
        try:
            ftp_dict[param] = self._get_common_data(server_name, param)
        except KeyError:
            ftp_dict[param] = None
        return ftp_dict

    def _get_ftp_server_name(self):
        for var in self.env_config_testline_variables().keys():
            if str(var).startswith('FTP'):
                return var

    def _get_sm_list(self, module, smod_hw_type):
        if smod_hw_type == 'FSMF':
            self.fsm_rel.append('FSMr3')
            return self.fsm3(module)
        elif smod_hw_type == 'ASIA':
            self.fsm_rel.append('FSMr4')
            return self.fsm4(module)
        else:
            logging.exception("SYSTEM MODULE Type not supported. Please create the configuration file manually")

    def _get_common_data_component(self, component):

        data = self.testline_config_variables[component]
        return data

    def _get_common_data(self, component, param):
        data = []
        env_config_testline_vars = self.env_config_testline_variables()
        for testline_var in env_config_testline_vars:
            if component in testline_var:
                data.append(self.testline_config_variables[testline_var][param])
        return data
